// Promotion-adjacent local fixture for the kr232 adapter.
//
// krc keeps named source variables in their frame slots at -O0/-O1, and
// kr232 does not promote recorded locals at any level until a register
// location producer exists (ADR 0052, Track A). This fixture is built at the
// default -O1 to prove the guarantee end to end: a local whose shape a
// promotion pass would like to keep in a register stays listed, with a correct
// value, across its live range and in a caller frame. The -O2 case is
// documented as unsupported in docs/symbol-verification-plan.md until Track B.
//
// Regenerated by tests/fixtures/kr232/regenerate.ps1 and checked by
// CheckFixtureDrift.cmake. Assertions live in tests/test_kr232_symbols.cpp and
// look lines up by token, never by number.

int eligible(int n) {
    int doubled = 0;
    doubled = n + n;
    doubled = doubled + 1;
    return doubled;
}

int caller(int seed) {
    int scaled = seed * 2;
    return eligible(scaled);
}

int address_taken(int n) {
    volatile int sink = n;
    return sink;
}

int main(void) {
    int a = caller(5);
    int b = address_taken(3);
    return a + b;
}
